/**
 * @file scripts/dev/design/sd/formats/generated-css.ts
 * @package @devpulse/coldlight
 *
 * Generates typography.css, focus.css, scrollbars.css, keyframes.css
 * from token SSOT values. All output is token-referencing only.
 */

export function generateTypographyCSS(): string {
	return `/**
 * AUTO-GENERATED — DO NOT EDIT
 * Typography utilities — generated by pnpm ds:tokens:build
 */

@utility text-display {
	font-family: var(--font-display);
	letter-spacing: 0.05em;
	text-transform: uppercase;
}

@utility text-mono {
	font-family: var(--font-mono);
}

@utility text-sans {
	font-family: var(--font-sans);
}
`;
}

export function generateFocusCSS(): string {
	return `/**
 * AUTO-GENERATED — DO NOT EDIT
 * Focus ring styles — generated by pnpm ds:tokens:build
 */

@utility focus-ring {
	outline: 2px solid var(--border-focus);
	outline-offset: 2px;
}

@utility focus-glow {
	outline: none;
	box-shadow: 0 0 0 2px var(--border-focus), var(--glow-teal);
}
`;
}

export function generateScrollbarsCSS(): string {
	return `/**
 * AUTO-GENERATED — DO NOT EDIT
 * Scrollbar styles — generated by pnpm ds:tokens:build
 */

@utility scrollbar-thin {
	scrollbar-width: thin;
	scrollbar-color: var(--matte-medium) transparent;
}

@utility scrollbar-hidden {
	scrollbar-width: none;
	-ms-overflow-style: none;
}
`;
}

export function generateKeyframesCSS(): string {
	return `/**
 * AUTO-GENERATED — DO NOT EDIT
 * Animation keyframes — generated by pnpm ds:tokens:build
 */

@keyframes pulse-glow {
	0%, 100% { opacity: 1; }
	50% { opacity: 0.6; }
}

@keyframes fade-in {
	from { opacity: 0; }
	to { opacity: 1; }
}

@keyframes slide-up {
	from { transform: translateY(4px); opacity: 0; }
	to { transform: translateY(0); opacity: 1; }
}

@keyframes slide-down {
	from { transform: translateY(-4px); opacity: 0; }
	to { transform: translateY(0); opacity: 1; }
}

@keyframes scale-in {
	from { transform: scale(0.95); opacity: 0; }
	to { transform: scale(1); opacity: 1; }
}

@keyframes spin {
	from { transform: rotate(0deg); }
	to { transform: rotate(360deg); }
}
`;
}
